import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from '@/registry/ndeko/ui/sheet';

import { TallyfoldMark } from './brand-mark';
import { HEADER, type NavLink } from './data';
import { scrollToSection, sectionHashOf } from './section-link';

function currentAttributeOf(isCurrent: boolean) {
  if (isCurrent) {
    return 'page' as const;
  }
  return undefined;
}

type MobileSheetProps = {
  links: NavLink[];
  currentId: string | null;
};

export function MobileSheet({ links, currentId }: MobileSheetProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [shouldReturnFocus, setShouldReturnFocus] = useState(true);
  const pendingHashRef = useRef<string | null>(null);

  function changeOpen(open: boolean) {
    if (open) {
      setShouldReturnFocus(true);
    }
    setIsOpen(open);
  }

  function followLink(event: React.MouseEvent<HTMLElement>) {
    const href = event.currentTarget.getAttribute('href');
    const sectionHash = sectionHashOf(href);
    setShouldReturnFocus(false);
    setIsOpen(false);
    if (sectionHash === null) {
      return;
    }
    event.preventDefault();
    pendingHashRef.current = sectionHash;
  }

  function finishOpenChange(open: boolean) {
    const pendingHash = pendingHashRef.current;
    pendingHashRef.current = null;
    if (open) {
      return;
    }
    if (pendingHash === null) {
      return;
    }
    scrollToSection(pendingHash);
  }

  return (
    <Sheet
      open={isOpen}
      onOpenChange={changeOpen}
      onOpenChangeComplete={finishOpenChange}
    >
      <SheetTrigger
        render={
          <Button
            variant='ghost'
            size='icon'
            className='md:hidden'
            aria-label='Open menu'
          />
        }
      >
        <MenuIcon />
      </SheetTrigger>
      <SheetContent side='right' finalFocus={shouldReturnFocus}>
        <SheetHeader>
          <SheetTitle className='flex items-center gap-2'>
            <TallyfoldMark />
            Tallyfold
          </SheetTitle>
          <SheetDescription>{HEADER.tagline}</SheetDescription>
        </SheetHeader>
        <nav aria-label='Main'>
          <ul className='flex flex-col gap-0.5'>
            {links.map((link) => {
              const isCurrent = currentId === link.id;

              return (
                <li key={link.id}>
                  <a
                    href={link.href}
                    aria-current={currentAttributeOf(isCurrent)}
                    onClick={followLink}
                    className='text-foreground hover:bg-foreground/5 aria-[current=page]:bg-foreground/5 focus-visible:ring-ring/25 flex h-11 items-center justify-between rounded-md px-3 text-base font-medium transition-colors outline-none focus-visible:ring-[3px]'
                  >
                    {link.label}
                    {isCurrent && <SelectedMark />}
                  </a>
                </li>
              );
            })}
          </ul>
        </nav>
        <SheetFooter>
          <Button
            variant='outline'
            size='lg'
            nativeButton={false}
            render={<a href='#' />}
          >
            Sign in
          </Button>
          <Button
            size='lg'
            nativeButton={false}
            render={<a href={HEADER.actionHref} />}
            onClick={followLink}
          >
            {HEADER.action}
          </Button>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  );
}

const SECTION_HASH_PATTERN = /^#.+/;

export function sectionHashOf(href: string | null) {
  if (href === null) {
    return null;
  }
  const isSectionHash = SECTION_HASH_PATTERN.test(href);
  if (!isSectionHash) {
    return null;
  }
  return href;
}

export function scrollToSection(hash: string) {
  const id = hash.slice(1);
  const target = document.getElementById(id);
  target?.scrollIntoView();
}

'use client';

import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import { MinusIcon, PlusIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { PLAN, PRICING, PRICING_ANCHOR } from './data';
import { FeatureTable } from './feature-table';

const PRICE_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
};

const PRICE_FORMATTER = new Intl.NumberFormat('en-US', PRICE_FORMAT);

function formatPrice(amount: number) {
  return PRICE_FORMATTER.format(amount);
}

function seatsLabelOf(seats: number) {
  if (seats === 1) {
    return 'for 1 seat';
  }
  return `for ${seats} seats`;
}

function moreSeatsOf(seats: number) {
  const next = seats + 1;
  return Math.min(next, PLAN.maxSeats);
}

function fewerSeatsOf(seats: number) {
  const next = seats - 1;
  return Math.max(next, PLAN.minSeats);
}

export function Pricing() {
  const [seats, setSeats] = useState(PLAN.defaultSeats);
  const canRemoveSeat = seats > PLAN.minSeats;
  const canAddSeat = seats < PLAN.maxSeats;
  const total = seats * PLAN.pricePerSeat;
  const seatPrice = formatPrice(PLAN.pricePerSeat);
  const seatsLabel = seatsLabelOf(seats);

  function addSeat() {
    setSeats(moreSeatsOf);
  }

  function removeSeat() {
    setSeats(fewerSeatsOf);
  }

  return (
    <section
      id={PRICING_ANCHOR}
      className='px-4 py-16 sm:px-6 sm:py-24 lg:px-8'
    >
      <div className='mx-auto flex max-w-6xl flex-col gap-10 sm:gap-14'>
        <div className='flex max-w-2xl flex-col gap-3'>
          <h1 className='text-2xl font-semibold text-balance sm:text-3xl'>
            {PRICING.title}
          </h1>
          <p className='text-muted-foreground text-base text-pretty'>
            {PRICING.description}
          </p>
        </div>
        <div className='grid items-start gap-10 lg:grid-cols-[22rem_minmax(0,1fr)] lg:gap-16'>
          <article className='surface-brand flex flex-col gap-6 rounded-xl p-6 sm:p-7 lg:sticky lg:top-8'>
            <div className='flex flex-col gap-1.5'>
              <h2 className='text-sm font-medium'>{PLAN.name}</h2>
              <p className='text-muted-foreground text-[13px]'>
                {PLAN.description}
              </p>
            </div>
            <p className='flex items-baseline gap-1.5'>
              <span className='text-4xl font-semibold tabular-nums'>
                {seatPrice}
              </span>
              <span className='text-muted-foreground text-[13px]'>
                per seat, per month
              </span>
            </p>
            <div className='flex items-center justify-between gap-4'>
              <span id='marketing-03-seats' className='text-[13px] font-medium'>
                Seats
              </span>
              <div
                role='group'
                aria-labelledby='marketing-03-seats'
                className='bg-card hairline-ring ring-foreground/12 dark:bg-foreground/[0.04] dark:ring-foreground/15 inline-flex items-center gap-1 rounded-full p-0.5 shadow-[0_1px_2px_rgb(0_0_0/0.05)]'
              >
                <Button
                  variant='ghost'
                  size='icon-sm'
                  className='rounded-full'
                  aria-label='Remove a seat'
                  disabled={!canRemoveSeat}
                  focusableWhenDisabled
                  onClick={removeSeat}
                >
                  <MinusIcon />
                </Button>
                <MotionNumber
                  value={seats}
                  className='min-w-6 justify-center text-[13px] font-medium'
                />
                <Button
                  variant='ghost'
                  size='icon-sm'
                  className='rounded-full'
                  aria-label='Add a seat'
                  disabled={!canAddSeat}
                  focusableWhenDisabled
                  onClick={addSeat}
                >
                  <PlusIcon />
                </Button>
              </div>
            </div>
            <div
              aria-live='polite'
              className='bg-foreground/[0.03] flex items-baseline justify-between gap-3 rounded-lg px-3 py-2.5'
            >
              <span className='text-muted-foreground text-[13px]'>
                Total per month
              </span>
              <span className='flex items-baseline gap-1.5 text-sm'>
                <MotionNumber
                  value={total}
                  format={PRICE_FORMAT}
                  className='font-semibold'
                />
                <WordRoll
                  text={seatsLabel}
                  value={seats}
                  className='text-muted-foreground text-xs'
                />
              </span>
            </div>
            <Button size='lg' nativeButton={false} render={<a href='#' />}>
              {PLAN.action}
            </Button>
            <p className='text-muted-foreground text-xs'>{PLAN.footnote}</p>
          </article>
          <FeatureTable />
        </div>
      </div>
    </section>
  );
}

